import{_ as i,o as e,c as a,a3 as t}from"./chunks/framework.CchDE9cb.js";const k=JSON.parse('{"title":"Install with Docker","description":"Install CapacityLens with Docker Compose, from cloning the repository to a running, health-checked instance.","frontmatter":{"title":"Install with Docker","description":"Install CapacityLens with Docker Compose, from cloning the repository to a running, health-checked instance."},"headers":[],"relativePath":"self-hosting/install-with-docker.md","filePath":"self-hosting/install-with-docker.md","lastUpdated":null}'),n={name:"self-hosting/install-with-docker.md"};function l(h,s,o,p,r,d){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="install-with-docker" tabindex="-1">Install with Docker <a class="header-anchor" href="#install-with-docker" aria-label="Permalink to &quot;Install with Docker&quot;">​</a></h1><p>This is the shortest path to a running CapacityLens instance: one Docker Compose stack with the web app, the API and an automatic internal certificate, backed by SQLite on persistent volumes. It takes about ten minutes on a host that already has Docker installed, most of it waiting for the first build.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A host that can run Docker and Docker Compose. See <a href="https://docs.docker.com/engine/install/" target="_blank" rel="noreferrer">Docker&#39;s install instructions</a> for your OS.</li><li>Read <a href="/capacitylens/self-hosting/">Before you start</a> if you haven&#39;t already.</li><li><strong>Architecture</strong>: the packaged images are built from multi-architecture base images (<code>node</code>, <code>alpine</code>, <code>nginx-unprivileged</code>), which publish both <code>linux/amd64</code> and <code>linux/arm64</code>. CapacityLens itself is tested on x86-64; arm64 (including Apple Silicon and AWS Graviton hosts) should work but isn&#39;t independently tested — open an issue if you hit something arm64-specific.</li><li><strong>Resources</strong>: this is a small Node API and a static file server backed by SQLite, not a heavy stack. As rough guidance: 1 CPU core, 1 GB RAM and a few GB of disk (more if you keep a lot of backup snapshots) is enough for a single small team.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Clone the repository and copy the example environment file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Kevinjohn/capacitylens.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> capacitylens</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div></li><li><p>Generate two secrets — one for signing sessions, one for the first-owner setup token:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rand</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -base64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 48</span></span></code></pre></div><p>Run it twice and keep both values; you&#39;ll paste one into each of the two secret fields in the next step.</p></li><li><p>Open <code>.env</code> and set at least these values:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SMALLSASS_ACCOUNT_DEPLOYMENT_PROFILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">self-hosted-password</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SMALLSASS_ACCOUNT_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SMALLSASS_ACCOUNT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;first generated value&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SMALLSASS_ACCOUNT_PUBLIC_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://capacity.example.com</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SMALLSASS_ACCOUNT_SETUP_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;second generated value&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CAPACITYLENS_HTTPS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CAPACITYLENS_RATE_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">300</span></span></code></pre></div><p><code>SMALLSASS_ACCOUNT_PUBLIC_URL</code> must be the exact browser-facing origin. See <a href="/capacitylens/self-hosting/configuration">Configuration</a> for what every other variable does.</p></li><li><p>Build and start the stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>This also builds the <code>internal-tls</code> one-off service, which creates a private certificate authority and API certificate before the API or web service starts.</p></li><li><p>Watch the API come up:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span></span></code></pre></div><p>Press <code>Ctrl-C</code> to stop following once the log settles — the API doesn&#39;t print a single &quot;ready&quot; line, so a quiet log with no restart is what you&#39;re looking for.</p></li><li><p>Check the app is serving and the API is healthy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/api/health</span></span></code></pre></div><p>Expected output is a JSON object starting <code>{&quot;ok&quot;:true,...}</code>. With the packaged defaults, deep health is on, so you&#39;ll also see <code>db</code>, <code>audit</code>, <code>auditPending</code>, <code>backup</code> and <code>internalTls</code> fields — see <a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a> for what each one means.</p><p>In the <code>docker compose ps</code> output, <code>internal-tls</code> showing <code>Exited (0)</code> is expected — it&#39;s a one-shot job that creates the internal certificate and then exits successfully; it isn&#39;t meant to keep running. See <a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a> for how to check the certificate it created.</p></li><li><p>Put a TLS-terminating reverse proxy in front of port 8080 and finish sign-in setup. See <a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a> for the proxy, then enter <code>SMALLSASS_ACCOUNT_SETUP_TOKEN</code> as the first owner when you open the app through your domain.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Compose binds port 8080 to <code>127.0.0.1</code> by default — nothing outside the host can reach it until you add the reverse proxy in the next page.</p></div><h2 id="a-demo-only-no-backend-image" tabindex="-1">A demo-only, no-backend image <a class="header-anchor" href="#a-demo-only-no-backend-image" aria-label="Permalink to &quot;A demo-only, no-backend image&quot;">​</a></h2><p>If you just want to try the interface with no database and no sign-in, build the client-only image instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_CAPACITYLENS_DEMO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/</span></span></code></pre></div><p>Naming <code>web-client</code> explicitly is what matters — it starts only that service, with no API dependency and no certificate volume. Data resets on every page refresh; this mode is not a persistent installation.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>web-client</code> binds the same <code>127.0.0.1:8080</code> port as the real <code>web</code> service from the steps above. Don&#39;t run both on the same host at once — the second one to start will fail to bind the port, or worse, you&#39;ll end up unsure which one you&#39;re looking at. Give the demo its own port with <code>WEB_PORT</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WEB_PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8081</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> VITE_CAPACITYLENS_DEMO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8081/</span></span></code></pre></div></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/capacitylens/self-hosting/configuration">Configuration</a> to understand every environment variable you just set, plus the ones you didn&#39;t.</li><li><a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a> to put a real domain and certificate in front of the stack.</li></ul>`,14)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
